import { readFile } from 'node:fs/promises';
import { errorMessage } from '@sanity/workflow-engine';
export async function readDefinitionFiles(paths) {
    const files = await Promise.all(paths.map(async (path) => ({ path, value: parseJson(path, await readFile(path, 'utf8')) })));
    return files.flatMap(({ path, value }) => definitionEntries(path, value));
}
export function describeValidation(entries, report) {
    const passed = [];
    const failed = [];
    report.results.forEach((result, index) => {
        const label = entries[index]?.label;
        if (label === undefined) {
            throw new Error(`validation result ${index} has no matching definition entry`);
        }
        if (result.valid) {
            passed.push(`${label}: ${result.definition.name}`);
        }
        else {
            failed.push(`${label}: ${result.error}`);
        }
    });
    return { passed, failed };
}
function parseJson(path, source) {
    try {
        return JSON.parse(source);
    }
    catch (err) {
        throw new Error(`${path}: not valid JSON (${errorMessage(err)})`, { cause: err });
    }
}
function definitionEntries(path, value) {
    if (!Array.isArray(value)) {
        return [{ label: path, definition: definitionObject(value, path) }];
    }
    if (value.length === 0) {
        throw new Error(`${path}: the array holds no definitions`);
    }
    return value.map((item, index) => {
        const label = `${path}[${index}]`;
        return { label, definition: definitionObject(item, label) };
    });
}
function definitionObject(value, label) {
    if (!isJsonObject(value)) {
        throw new Error(`${label}: expected a workflow definition object, got ${jsonKind(value)}`);
    }
    return value;
}
function isJsonObject(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function jsonKind(value) {
    if (value === null) {
        return 'null';
    }
    return Array.isArray(value) ? 'an array' : typeof value;
}
